macroData.command:
const version = "13.0.61";
try {
  if (args[0].tag !== "OnUse" || args[0].macroPass !== "postActiveEffects") return;
  const actor = rolledItem.parent;
  const unarmed = actor.items.find(i => i.system.identifier === "unarmed-strike" || i.name === "Unarmed Strike");
  if (!unarmed) {
    ui.notifications.warn("No Unarmed Strike found on this actor.");
    return;
  }
  const existing = unarmed.effects.find(e => e.name === "Elemental Attunement" && e.type === "enchantment");
  if (existing) await existing.delete();
  const effectData = {
    name: "Elemental Attunement",
    img: macroItem.img,
    type: "enchantment",
    origin: macroActivity.uuid,
    disabled: false,
    duration: { value: 10, units: "minutes" },
    start: { time: game.time.worldTime },
    description: "Your Unarmed Strike reach is 10 ft greater and can deal Acid, Cold, Fire, Lightning, or Thunder damage.",
    changes: [
      { key: "system.range.reach", value: "+10", mode: CONST.ACTIVE_EFFECT_MODES.ADD },
      { key: "system.damage.base.types", value: "acid", mode: CONST.ACTIVE_EFFECT_MODES.ADD },
      { key: "system.damage.base.types", value: "cold", mode: CONST.ACTIVE_EFFECT_MODES.ADD },
      { key: "system.damage.base.types", value: "fire", mode: CONST.ACTIVE_EFFECT_MODES.ADD },
      { key: "system.damage.base.types", value: "lightning", mode: CONST.ACTIVE_EFFECT_MODES.ADD },
      { key: "system.damage.base.types", value: "thunder", mode: CONST.ACTIVE_EFFECT_MODES.ADD }
    ],
    flags: {
      dae: {
        disableIncapacitated: true
      }
    }
  };
  const [created] = await unarmed.createEmbeddedDocuments("ActiveEffect", [effectData]);
  if (created) {
    ChatMessage.create({
      content: `<p><strong>${actor.name}</strong> imbues their Unarmed Strike with elemental energy for 10 minutes.</p>`,
      speaker: ChatMessage.getSpeaker({ actor })
    });
  }
} catch (err) {
  console.error(`Elemental Attunement Imbue ${version}`, err);
}

const version = "14.0.6";
try {
  if (args[0].tag !== "OnUse" || args[0].macroPass !== "postActiveEffects") return;
  const workflow = args[0].workflow;
  if (!workflow) return;
  const casterToken = canvas.tokens.get(workflow.tokenId);
  if (!casterToken || !workflow.failedSaves.size) return;
  const direction = await foundry.applications.api.DialogV2.wait({
    window: { title: "Elemental Push/Pull" },
    content: "<p>Move the target toward or away from you?</p>",
    buttons: [
      { action: "push", label: "Push (Away)", icon: "fas fa-arrow-right" },
      { action: "pull", label: "Pull (Toward)", icon: "fas fa-arrow-left" },
      { action: "none", label: "No Movement" }
    ],
    close: () => "none"
  });
  if (direction === "none") return;
  const distance = direction === "push" ? 10 : -10;
  for (const target of workflow.failedSaves) {
    await MidiQOL.moveTokenAwayFromPoint(target, distance, casterToken.center);
  }
} catch (err) {
  console.error(`Elemental Push ${version}`, err);
}
